 107	static void *probe_game_thread(void *arg)
 108	{
 109	  struct probe_imu_sample sample;
 110	  struct probe_game_command command;
 111	  struct probe_game_result result;
 112	  uint64_t imu_samples = 0;
 113	  uint64_t last_sample_us = 0;
 114	  uint32_t imu_gaps = 0;
 115	  uint32_t game_session = 1;
 116	  uint32_t combo = 0;
 117	
 118	  (void)arg;
 119	  printf("openvela_ble_probe: game thread entered\n");
 120	
 121	  for (;;)
 122	    {
 123	      while (sem_wait(&g_game_sem) < 0 && errno == EINTR)
 124	        {
 125	        }
 126	
 127	      while (probe_game_take_imu(&sample))
 128	        {
 129	          imu_samples++;
 130	          last_sample_us = sample.monotonic_us;
 131	          if ((sample.flags & PROBE_IMU_SAMPLE_FLAG_GAP) != 0)
 132	            {
 133	              imu_gaps++;
 134	            }
 135	        }
 136	
 137	      while (probe_game_take_command(&command))
 138	        {
 139	          memset(&result, 0, sizeof(result));
 140	          result.connection_generation = command.connection_generation;
 141	          result.gesture = command.gesture;
 142	          result.confidence = command.confidence;
 143	          result.flags = command.flags;
 144	          result.battery = command.battery;
 145	          result.game_session = game_session;
 146	          result.timing_error_ms = 0;
 147	          if (probe_test_judgement(command.gesture) == PROBE_JUDGEMENT_MISS)
 148	            {
 149	              combo = 0;
 150	            }
 151	          else
 152	            {
 153	              combo++;
 154	            }
 155	
 156	          result.combo = combo;
 157	          probe_game_publish_result(&result, imu_samples, imu_gaps);
 158	          printf("openvela_ble_probe: game test judgement gesture=%u"
 159	                 " combo=%lu imu_time_us=%llu\n",
 160	                 command.gesture, (unsigned long)combo,
 161	                 (unsigned long long)last_sample_us);
 162	        }
 163	    }
 164	
 165	  return NULL;
 166	}
