 168	int probe_game_start(void)
 169	{
 170	  int ret;
 171	
 172	  if (__atomic_exchange_n(&g_started, true, __ATOMIC_ACQ_REL))
 173	    {
 174	      return 0;
 175	    }
 176	
 177	  if (sem_init(&g_game_sem, 0, 0) < 0)
 178	    {
 179	      __atomic_store_n(&g_started, false, __ATOMIC_RELEASE);
 180	      return -errno;
 181	    }
 182	
 183	  ret = pthread_create(&g_game_thread, NULL, probe_game_thread, NULL);
 184	  if (ret != 0)
 185	    {
 186	      sem_destroy(&g_game_sem);
 187	      __atomic_store_n(&g_started, false, __ATOMIC_RELEASE);
 188	      return -ret;
 189	    }
 190	
 191	  pthread_detach(g_game_thread);
 192	  return 0;
 193	}
