 199	
 200	  if (!__atomic_load_n(&g_started, __ATOMIC_ACQUIRE))
 201	    {
 202	      return false;
 203	    }
 204	
 205	  if (head - tail >= PROBE_IMU_RING_DEPTH)
 206	    {
