 36	static bool probe_game_take_imu(struct probe_imu_sample *sample)
 37	{
 38	  uint32_t tail = __atomic_load_n(&g_imu_tail, __ATOMIC_RELAXED);
 39	  uint32_t head = __atomic_load_n(&g_imu_head, __ATOMIC_ACQUIRE);
 40	
 41	  if (tail == head)
 42	    {
 43	      return false;
 44	    }
 45	
 46	  memcpy(sample, &g_imu_ring[tail % PROBE_IMU_RING_DEPTH], sizeof(*sample));
 47	  __atomic_store_n(&g_imu_tail, tail + 1, __ATOMIC_RELEASE);
 48	  return true;
 49	}
 50	
 51	static bool probe_game_take_command(struct probe_game_command *command)
 52	{
 53	  uint32_t tail = __atomic_load_n(&g_command_tail, __ATOMIC_RELAXED);
 54	  uint32_t head = __atomic_load_n(&g_command_head, __ATOMIC_ACQUIRE);
 55	
 56	  if (tail == head)
 57	    {
 58	      return false;
 59	    }
 60	
 61	  memcpy(command, &g_command_ring[tail % PROBE_COMMAND_RING_DEPTH],
 62	         sizeof(*command));
 63	  __atomic_store_n(&g_command_tail, tail + 1, __ATOMIC_RELEASE);
 64	  return true;
 65	}
