 67	static enum probe_judgement_e probe_test_judgement(uint8_t gesture)
 68	{
 69	  /* Test-only visible mapping; this is not an action recognition algorithm. */
 70	
 71	  if (gesture == 1)
 72	    {
 73	      return PROBE_JUDGEMENT_GOOD;
 74	    }
 75	
 76	  if (gesture == 2)
 77	    {
 78	      return PROBE_JUDGEMENT_MISS;
 79	    }
 80	
 81	  return PROBE_JUDGEMENT_PERFECT;
 82	}
