195	bool probe_game_submit_imu(const struct probe_imu_sample *sample)
196	{
197	  uint32_t head = __atomic_load_n(&g_imu_head, __ATOMIC_RELAXED);
198	  uint32_t tail = __atomic_load_n(&g_imu_tail, __ATOMIC_ACQUIRE);
199	
200	  if (!__atomic_load_n(&g_started, __ATOMIC_ACQUIRE))
201	    {
202	      return false;
203	    }
204	
205	  if (head - tail >= PROBE_IMU_RING_DEPTH)
206	    {
207	      __atomic_fetch_add(&g_imu_ring_full, 1, __ATOMIC_RELAXED);
208	      return false;
209	    }
210	
211	  memcpy(&g_imu_ring[head % PROBE_IMU_RING_DEPTH], sample, sizeof(*sample));
212	  __atomic_store_n(&g_imu_head, head + 1, __ATOMIC_RELEASE);
213	  sem_post(&g_game_sem);
214	  return true;
215	}
