159	int probe_ui_start(probe_ui_ble_connected_t connected, bool imu_available)
160	{
161	  int ret;
162	
163	  if (__atomic_exchange_n(&g_started, true, __ATOMIC_ACQ_REL))
164	    {
165	      return 0;
166	    }
167	
168	  g_connected = connected;
169	  g_imu_available = imu_available;
170	  ret = pthread_create(&g_ui_thread, NULL, probe_ui_thread, NULL);
171	  if (ret != 0)
172	    {
173	      __atomic_store_n(&g_started, false, __ATOMIC_RELEASE);
174	      return -ret;
175	    }
176	
177	  pthread_detach(g_ui_thread);
178	  return 0;
179	}
