185	
186	  if (!__atomic_load_n(&g_started, __ATOMIC_ACQUIRE))
187	    {
188	      return false;
189	    }
190	
191	  if (head - tail >= PROBE_UI_RING_DEPTH)
192	    {
193	      __atomic_fetch_add(&g_ui_full, 1, __ATOMIC_RELAXED);
194	      return false;
195	    }
196	
197	  memcpy(&g_ui_ring[head % PROBE_UI_RING_DEPTH], result, sizeof(*result));
198	  __atomic_store_n(&g_ui_head, head + 1, __ATOMIC_RELEASE);
199	  return true;
200	}

