 84	static void probe_game_publish_result(const struct probe_game_result *result,
 85	                                      uint64_t imu_samples,
 86	                                      uint32_t imu_gaps)
 87	{
 88	  struct probe_ui_result ui;
 89	
 90	  ui.judgement = probe_test_judgement(result->gesture);
 91	  ui.combo = result->combo;
 92	  ui.imu_samples = imu_samples;
 93	  ui.imu_gaps = imu_gaps;
 94	
 95	  probe_local_feedback(result);
 96	  if (!probe_ui_submit(&ui))
 97	    {
 98	      __atomic_fetch_add(&g_ui_ring_full, 1, __ATOMIC_RELAXED);
 99	    }
100	
101	  if (!probe_game_submit_judgement(result))
102	    {
103	      __atomic_fetch_add(&g_result_ring_full, 1, __ATOMIC_RELAXED);
104	    }
105	}
