 70	
 71	  if (gesture == 1)
 72	    {
 73	      return PROBE_JUDGEMENT_GOOD;
 74	    }
 75	
 76	  if (gesture == 2)
 77	    {
 78	      return PROBE_JUDGEMENT_MISS;
