421	static uint64_t probe_timespec_us(const struct timespec *time)
422	{
423	  return (uint64_t)time->tv_sec * 1000000ULL +
424	         (uint64_t)time->tv_nsec / 1000ULL;
425	}
426	
427	static void probe_timespec_add_ms(struct timespec *time, uint32_t ms)
428	{
429	  uint64_t nsec = (uint64_t)time->tv_nsec +
430	                  (uint64_t)ms * 1000000ULL;
431	
432	  time->tv_sec += (time_t)(nsec / 1000000000ULL);
433	  time->tv_nsec = (long)(nsec % 1000000000ULL);
434	}
