1901	    {
1902	      if (clock_gettime(CLOCK_REALTIME, &wait_until) < 0)
1903	        {
1904	          continue;
1905	        }
1906	
1907	      wait_until.tv_nsec += PROBE_GESTURE_WORKER_POLL_MS * 1000000L;
1908	      if (wait_until.tv_nsec >= 1000000000L)
1909	        {
1910	          wait_until.tv_sec++;
1911	          wait_until.tv_nsec -= 1000000000L;
1912	        }
1913	
1914	      do
1915	        {
1916	          wait_status = sem_timedwait(&g_rx_sem, &wait_until);
1917	        }
1918	      while (wait_status < 0 && errno == EINTR);
1919	
1920	      if (wait_status < 0 && errno != ETIMEDOUT)
1921	        {
1922	          continue;
1923	        }
1924	
1925	      tail = __atomic_load_n(&g_rx_tail, __ATOMIC_RELAXED);
1926	      head = __atomic_load_n(&g_rx_head, __ATOMIC_ACQUIRE);
1927	      have_slot = tail != head;
1928	      if (have_slot)
1929	        {
1930	          memcpy(&slot, &g_rx_queue[tail % PROBE_RX_QUEUE_DEPTH],
1931	                 sizeof(slot));
1932	          __atomic_store_n(&g_rx_tail, tail + 1, __ATOMIC_RELEASE);
1933	        }
1934	
1935	      pthread_mutex_lock(&g_state_lock);
1936	      generation = __atomic_load_n(&g_connection_generation,
1937	                                   __ATOMIC_ACQUIRE);
1938	      connected = g_peer_connected;
1939	      memcpy(&peer_addr, &g_peer_addr, sizeof(peer_addr));
1940	      pthread_mutex_unlock(&g_state_lock);
1941	
1942	      if (generation != active_generation)
1943	        {
1944	          memset(&g_throughput, 0, sizeof(g_throughput));
1945	          memset(&g_reliable39, 0, sizeof(g_reliable39));
1946	          active_generation = generation;
1947	        }
1948	
1949	      if (have_slot &&
1950	          (!connected || slot.connection_generation != generation ||
1951	           memcmp(&slot.addr, &peer_addr, sizeof(peer_addr)) != 0))
1952	        {
1953	          __atomic_fetch_add(&g_rx_stale, 1, __ATOMIC_RELAXED);
1954	          have_slot = false;
1955	        }
1956	
1957	      if (have_slot)
1958	        {
1959	          probe_process_frame(g_service_handle, slot.value, slot.length,
1960	                              generation);
1961	        }
1962	
1963	      while (probe_game_take_ble_result(&game_result))
1964	        {
1965	          int publish_status;
1966	
1967	          if (!connected || game_result.connection_generation != generation)
1968	            {
1969	              printf("openvela_ble_probe: stale game result dropped"
1970	                     " generation=%lu current=%lu\n",
1971	                     (unsigned long)game_result.connection_generation,
1972	                     (unsigned long)generation);
1973	              continue;
1974	            }
1975	
1976	          publish_status = probe_publish_gesture(game_result.gesture,
1977	                                                 game_result.confidence,
1978	                                                 game_result.flags,
1979	                                                 game_result.battery);
1980	
1981	          printf("openvela_ble_probe: game result publish gesture=%u"
1982	                 " session=%lu combo=%lu status=%d\n",
1983	                 game_result.gesture,
1984	                 (unsigned long)game_result.game_session,
1985	                 (unsigned long)game_result.combo, publish_status);
1986	        }
1987	
1988	      probe_process_gesture_tx();
1989	    }
1990	
1991	  return NULL;
1992	}
