1355	  if (used >= PROBE_GESTURE_QUEUE_DEPTH)
1356	    {
1357	      g_gesture_queue_full++;
1358	      pthread_mutex_unlock(&g_state_lock);
1359	      return -1;
1360	    }
1361	
1362	  synced = g_gesture_time_synced;
1363	  timestamp_ms = synced ?
1364	    g_gesture_sync_unix_ms +
1365	      (monotonic_ms - g_gesture_sync_monotonic_ms) : monotonic_ms;
1366	  if (synced)
1367	    {
1368	      flags |= 0x01;
1369	    }
1370	  else
1371	    {
1372	      flags &= (uint8_t)~0x01;
1373	    }
1374	
1375	  record = &g_gesture_queue[g_gesture_rx_head %
1376	                            PROBE_GESTURE_QUEUE_DEPTH];
1377	  memset(record, 0, sizeof(*record));
1378	  record->connection_generation = generation;
1379	  record->packet_id = g_gesture_next_packet_id++;
1380	  record->event[0] = 1;
1381	  record->event[1] = 0x01;
1382	  probe_put_le16(&record->event[2], record->packet_id);
1383	  probe_put_le64(&record->event[4], timestamp_ms);
1384	  record->event[12] = gesture;
1385	  record->event[13] = confidence;
1860	    }
1861	
1862	  slot = &g_rx_queue[head % PROBE_RX_QUEUE_DEPTH];
1863	  memcpy(&slot->addr, addr, sizeof(slot->addr));
1864	  slot->connection_generation = generation;
1865	  slot->length = length;
1866	  slot->offset = offset;
1867	  memcpy(slot->value, value, length);
1868	  used++;
1869	  if (used >
1870	      __atomic_load_n(&g_rx_high_water, __ATOMIC_RELAXED))
1871	    {
1872	      __atomic_store_n(&g_rx_high_water, used, __ATOMIC_RELAXED);
1873	    }
1874	
1875	  /* Publish only after the complete slot is visible to the consumer. */
1876	
1877	  __atomic_store_n(&g_rx_head, head + 1, __ATOMIC_RELEASE);
1878	
1879	  __atomic_fetch_add(&g_rx_enqueued, 1, __ATOMIC_RELAXED);
1880	  sem_post(&g_rx_sem);
1881	  return length;
1882	}
