 217	bool probe_game_submit_command(const struct probe_game_command *command)
 218	{
 219	  uint32_t head = __atomic_load_n(&g_command_head, __ATOMIC_RELAXED);
 220	  uint32_t tail = __atomic_load_n(&g_command_tail, __ATOMIC_ACQUIRE);
 221	
 222	  if (!__atomic_load_n(&g_started, __ATOMIC_ACQUIRE))
 223	    {
 224	      return false;
 225	    }
 226	
 227	  if (head - tail >= PROBE_COMMAND_RING_DEPTH)
 228	    {
 229	      __atomic_fetch_add(&g_command_ring_full, 1, __ATOMIC_RELAXED);
 230	      return false;
 231	    }
 232	
 233	  memcpy(&g_command_ring[head % PROBE_COMMAND_RING_DEPTH], command,
 234	         sizeof(*command));
 235	  __atomic_store_n(&g_command_head, head + 1, __ATOMIC_RELEASE);
 236	  sem_post(&g_game_sem);
 237	  return true;
 238	}
