 244	
 245	  if (!__atomic_load_n(&g_started, __ATOMIC_ACQUIRE))
 246	    {
 247	      return false;
 248	    }
 249	
 250	  if (head - tail >= PROBE_RESULT_RING_DEPTH)
 251	    {
 252	      return false;
 253	    }
