1565	static void probe_process_frame(gatts_handle_t srv_handle,
1566	                                const uint8_t *value, uint16_t length,
1567	                                uint32_t connection_generation)
1568	{
1569	  uint8_t response[21];
1570	  uint8_t *reply;
1571	  uint16_t reply_len;
1572	  uint32_t elapsed_ms;
1573	  uint32_t id_or_seq;
1574	  uint32_t seq;
1575	  bt_status_t status;
1576	
1577	  if (length == 4 && memcmp(value, "PING", 4) == 0)
1578	    {
1579	      reply = g_pong;
1580	      reply_len = sizeof(g_pong);
1581	      printf("openvela_ble_probe: RX PING\n");
1582	    }
1583	  else if (length >= 1 && value[0] == 0x01)
1584	    {
1585	      if (length < 5)
1586	        {
1587	          printf("openvela_ble_probe: short binary PING length=%u\n",
1588	                 length);
1589	          return;
1590	        }
1591	
1592	      id_or_seq = probe_get_le32(&value[1]);
1593	      response[0] = 0x81;
1594	      probe_put_le32(&response[1], id_or_seq);
1595	      printf("openvela_ble_probe: RX binary PING seq=%lu\n",
1596	             (unsigned long)id_or_seq);
1597	      status = probe_notify(srv_handle, response, 5);
1598	      printf("openvela_ble_probe: TX binary PONG status=%d\n", status);
1599	      return;
1600	    }
1601	  else if (length >= 1 && value[0] == PROBE_RELIABLE39_REQUEST_TYPE)
1602	    {
1603	      uint16_t expected_crc;
1604	      uint16_t received_crc;
1605	
