   449	      PROBE_IMU_FIFO_CTRL3,
   450	      PROBE_IMU_FIFO_CTRL4,
   451	      PROBE_IMU_FIFO_CTRL5,
   452	      PROBE_IMU_DRDY_PULSE_CFG_G,
   453	      PROBE_IMU_INT1_CTRL,
   454	      PROBE_IMU_CTRL1_XL,
   455	      PROBE_IMU_CTRL2_G,
   456	      PROBE_IMU_CTRL3_C
   457	    };
   458	  bool saved_valid[sizeof(registers)] = {false};
   459	  uint8_t saved[sizeof(registers)] = {0};
   460	  uint8_t status[4];
   461	  uint8_t word[2];
   462	  struct timespec start_time;
   463	  struct timespec wait_until;
   464	  struct timespec now;
   465	  uint64_t start_us = 0;
   466	  uint64_t end_us = 0;
