   470	  int16_t gyro[3] = {0};
   471	  int16_t accel[3] = {0};
   472	  uint32_t fifo_wake_count = 0;
   473	  uint32_t fifo_words_read = 0;
   474	  uint32_t gyro_samples = 0;
   475	  uint32_t accel_samples = 0;
   476	  uint32_t paired_samples = 0;
   477	  uint32_t startup_discarded_words = 0;
   478	  uint32_t fifo_watermark_events = 0;
   479	  uint32_t fifo_overrun = 0;
   480	  uint32_t fifo_smart_full = 0;
   481	  uint32_t max_fifo_depth_words = 0;
   482	  uint32_t unexpected_frames = 0;
   483	  uint32_t i2c_errors = 0;
   484	  uint32_t timeouts = 0;
   485	  uint32_t fifo_irq_count;
   486	  uint16_t end_depth_words = 0;
   487	  uint8_t expected_pattern = 0;
   488	  uint8_t gyro_axis_mask = 0;
   489	  uint8_t accel_axis_mask = 0;
   490	  uint8_t discard_remaining = 0;
   491	  bool pattern_aligned = false;
   492	  bool expected_valid = false;
   493	  bool gyro_ready = false;
   494	  bool irq_enabled = false;
   495	  bool semaphore_initialized = false;
   496	  bool fifo_started = false;
   497	  int restore_status = 0;
   498	  int cleanup_ret;
   499	  int wait_status;
   500	  int fd;
   501	  int ret;
   502	  size_t i;
   503	
   504	  (void)arg;
   505	  printf("openvela_ble_probe: IMU FIFO thread entered\n");
   506	  __atomic_store_n(&g_imu_drdy_irq_count, 0, __ATOMIC_RELAXED);
   507	  fd = open(PROBE_IMU_I2C_DEV, O_RDONLY);
   508	  if (fd < 0)
   509	    {
   510	      printf("openvela_ble_probe: IMU raw open %s failed errno=%d\n",
   511	             PROBE_IMU_I2C_DEV, errno);
   512	      return NULL;
   513	    }
   514	
   515	  for (i = 0; i < sizeof(registers); i++)
   516	    {
   517	      ret = probe_imu_read(fd, PROBE_IMU_ADDR, registers[i], &saved[i], 1);
   518	      if (ret != 0)
   519	        {
   520	          printf("openvela_ble_probe: IMU raw save reg=0x%02x failed"
   521	                 " status=%d\n", registers[i], ret);
