   523	        }
   524	
   525	      saved_valid[i] = true;
   526	    }
   527	
   528	  ret = board_imu_int1_disable();
   529	  if (ret != 0)
   530	    {
   531	      printf("openvela_ble_probe: IMU FIFO initial IRQ disable failed"
   532	             " status=%d\n", ret);
   533	      goto restore;
   534	    }
   535	
   536	  ret = probe_imu_write_verify(fd, PROBE_IMU_ADDR, PROBE_IMU_FIFO_CTRL5,
   537	                               PROBE_IMU_FIFO_BYPASS);
   538	  if (ret == 0)
   539	    {
   540	      ret = probe_imu_write_verify(fd, PROBE_IMU_ADDR, PROBE_IMU_CTRL3_C,
   541	                                   PROBE_IMU_CTRL3_C_BDU_IF_INC);
   542	    }
   543	
   544	  if (ret == 0)
   545	    {
   546	      ret = probe_imu_write_verify(fd, PROBE_IMU_ADDR, PROBE_IMU_CTRL1_XL,
   547	                                   PROBE_IMU_CTRL1_XL_104HZ_4G);
   548	    }
   549	
   550	  if (ret == 0)
   551	    {
   552	      ret = probe_imu_write_verify(fd, PROBE_IMU_ADDR, PROBE_IMU_CTRL2_G,
   553	                                   PROBE_IMU_CTRL2_G_104HZ_500DPS);
   554	    }
   555	
   556	  if (ret == 0)
   557	    {
   558	      ret = probe_imu_write_verify(fd, PROBE_IMU_ADDR,
   559	                                   PROBE_IMU_FIFO_CTRL1, 0x78);
   560	    }
   561	
   562	  if (ret == 0)
   563	    {
   564	      ret = probe_imu_write_verify(fd, PROBE_IMU_ADDR,
   565	                                   PROBE_IMU_FIFO_CTRL2, 0x00);
   566	    }
   567	
   568	  if (ret == 0)
   569	    {
   570	      ret = probe_imu_write_verify(fd, PROBE_IMU_ADDR,
   571	                                   PROBE_IMU_FIFO_CTRL3,
   572	                                   PROBE_IMU_FIFO_CTRL3_GY_XL);
   573	    }
   574	
   575	  if (ret == 0)
   576	    {
   577	      ret = probe_imu_write_verify(fd, PROBE_IMU_ADDR,
   578	                                   PROBE_IMU_FIFO_CTRL4, 0x00);
   579	    }
   580	
   581	  if (ret == 0)
   582	    {
   583	      uint8_t int1_value = saved[6] & ~(0x01 | 0x02 | 0x08 | 0x10);
   584	
   585	      int1_value |= PROBE_IMU_INT1_FIFO_FTH;
   586	      ret = probe_imu_write_verify(fd, PROBE_IMU_ADDR,
   587	                                   PROBE_IMU_INT1_CTRL, int1_value);
   588	    }
   589	
   590	  if (ret != 0)
   591	    {
   592	      printf("openvela_ble_probe: IMU FIFO configure failed status=%d\n",
   593	             ret);
   594	      goto restore;
   595	    }
   596	
   597	  if (sem_init(&g_imu_drdy_sem, 0, 0) < 0)
   598	    {
   599	      printf("openvela_ble_probe: IMU FIFO semaphore init failed errno=%d\n",
   600	             errno);
   601	      goto restore;
   602	    }
   603	
   604	  semaphore_initialized = true;
   605	
   606	  ret = board_imu_int1_enable(probe_imu_int1_isr, NULL);
   607	  if (ret != 0)
   608	    {
   609	      printf("openvela_ble_probe: IMU FIFO IRQ enable failed status=%d\n",
   610	             ret);
   611	      goto restore;
   612	    }
   613	
   614	  irq_enabled = true;
   615	  ret = probe_imu_write_verify(fd, PROBE_IMU_ADDR, PROBE_IMU_FIFO_CTRL5,
   616	                               PROBE_IMU_FIFO_104HZ_CONTINUOUS);
   617	  if (ret != 0)
   618	    {
   619	      printf("openvela_ble_probe: IMU FIFO start failed status=%d\n", ret);
   620	      goto stop_irq;
   621	    }
   622	
   623	  fifo_started = true;
   624	
   625	  printf("openvela_ble_probe: IMU FIFO config watermark_words=120"
   626	         " fifo_ctrl3=0x09 fifo_ctrl5=0x26\n");
   627	
   628	  if (clock_gettime(CLOCK_MONOTONIC, &start_time) < 0)
   629	    {
   630	      printf("openvela_ble_probe: IMU DRDY clock_gettime failed errno=%d\n",
   631	             errno);
   632	      goto stop_irq;
   633	    }
   634	
   635	  start_us = probe_timespec_us(&start_time);
   636	  next_log_us = start_us + 10000000ULL;
   637	
   638	  /* This producer is intentionally long-lived.  The cleanup path below is
   639	   * retained for configuration, I/O, or a future explicit-stop failure.
   640	   */
   641	
   642	  for (;;)
   643	    {
   644	      uint64_t now_us;
   645	      bool wake_watermark_seen = false;
   646	      bool wake_smart_full_seen = false;
   647	      bool wake_overrun_seen = false;
   648	
   649	      if (clock_gettime(CLOCK_MONOTONIC, &now) < 0)
   650	        {
   651	          printf("openvela_ble_probe: IMU FIFO clock read failed errno=%d\n",
   652	                 errno);
   653	          break;
   654	        }
   655	
   656	      now_us = probe_timespec_us(&now);
   657	      if (now_us >= next_log_us)
   658	        {
   659	          fifo_irq_count = __atomic_load_n(&g_imu_drdy_irq_count,
   660	                                           __ATOMIC_RELAXED);
   661	          printf("openvela_ble_probe: IMU FIFO progress elapsed_ms=%llu"
   662	                 " fifo_irq_count=%lu fifo_wake_count=%lu"
   663	                 " fifo_words_read=%lu gyro_samples=%lu accel_samples=%lu"
   664	                 " paired_six_axis_samples=%lu fifo_overrun=%lu"
   665	                 " fifo_smart_full=%lu max_fifo_depth_words=%lu"
   666	                 " unexpected=%lu i2c_errors=%lu timeouts=%lu\n",
   667	                 (unsigned long long)((now_us - start_us) / 1000),
   668	                 (unsigned long)fifo_irq_count,
   669	                 (unsigned long)fifo_wake_count,
   670	                 (unsigned long)fifo_words_read,
   671	                 (unsigned long)gyro_samples,
   672	                 (unsigned long)accel_samples,
   673	                 (unsigned long)paired_samples,
   674	                 (unsigned long)fifo_overrun,
   675	                 (unsigned long)fifo_smart_full,
   676	                 (unsigned long)max_fifo_depth_words,
   677	                 (unsigned long)unexpected_frames,
   678	                 (unsigned long)i2c_errors, (unsigned long)timeouts);
   679	          next_log_us = now_us + 10000000ULL;
   680	        }
   681	
   682	      wait_until = now;
   683	      probe_timespec_add_ms(&wait_until, PROBE_IMU_DRDY_WAIT_MS);
   684	
   685	      do
   686	        {
   687	          wait_status = sem_clockwait(&g_imu_drdy_sem, CLOCK_MONOTONIC,
   688	                                      &wait_until);
   689	        }
   690	      while (wait_status < 0 && errno == EINTR);
   691	
   692	      if (wait_status < 0)
   693	        {
   694	          if (errno == ETIMEDOUT)
   695	            {
   696	              timeouts++;
   697	              continue;
   698	            }
   699	
   700	          printf("openvela_ble_probe: IMU FIFO semaphore wait failed"
   701	                 " errno=%d\n", errno);
   702	          break;
   703	        }
   704	
   705	      fifo_wake_count++;
   706	
   707	      for (;;)
   708	        {
   709	          uint16_t depth;
   710	          uint16_t pattern;
   711	          uint16_t words_to_read;
   712	          uint64_t drain_now_us;
   713	          bool watermark;
   714	          bool empty;
   715	          bool smart_full;
   716	          bool overrun;
   717	
   718	          ret = probe_imu_read(fd, PROBE_IMU_ADDR,
   719	                               PROBE_IMU_FIFO_STATUS1,
   720	                               status, sizeof(status));
   721	          if (ret != 0)
   722	            {
   723	              i2c_errors++;
   724	              expected_valid = false;
   725	              break;
   726	            }
   727	
   728	          if (clock_gettime(CLOCK_MONOTONIC, &now) < 0)
   729	            {
   730	              printf("openvela_ble_probe: IMU FIFO timestamp failed"
   731	                     " errno=%d\n", errno);
   732	              goto stop_irq;
   733	            }
   734	
   735	          drain_now_us = probe_timespec_us(&now);
   736	
   737	          depth = (uint16_t)status[0] |
   738	                  ((uint16_t)(status[1] & 0x07) << 8);
   739	          empty = (status[1] & 0x10) != 0;
   740	          smart_full = (status[1] & 0x20) != 0;
   741	          overrun = (status[1] & 0x40) != 0;
   742	          watermark = (status[1] & 0x80) != 0;
   743	          pattern = (uint16_t)status[2] |
   744	                    ((uint16_t)(status[3] & 0x03) << 8);
   745	
   746	          if (depth > max_fifo_depth_words)
   747	            {
   748	              max_fifo_depth_words = depth;
   749	            }
   750	
   751	          if (watermark && !wake_watermark_seen)
   752	            {
   753	              fifo_watermark_events++;
   754	              wake_watermark_seen = true;
   755	            }
   756	
   757	          if (smart_full && !wake_smart_full_seen)
   758	            {
   759	              fifo_smart_full++;
   760	              wake_smart_full_seen = true;
   761	            }
   762	
   763	          if (overrun && !wake_overrun_seen)
   764	            {
   765	              fifo_overrun++;
   766	              wake_overrun_seen = true;
   767	            }
   768	
   769	          if (empty || depth == 0)
   770	            {
   771	              break;
   772	            }
   773	
   774	          words_to_read = depth;
   775	          while (words_to_read-- > 0)
   776	            {
   777	              struct probe_imu_sample sample;
   778	              uint8_t pattern_word = (uint8_t)(pattern %
   779	                                                PROBE_IMU_FIFO_PATTERN_WORDS);
   780	              int16_t raw;
   781	
   782	              if (expected_valid && pattern_word != expected_pattern)
   783	                {
   784	                  unexpected_frames++;
   785	                  gyro_axis_mask = 0;
   786	                  accel_axis_mask = 0;
   787	                  gyro_ready = false;
   788	                }
   789	
   790	              ret = probe_imu_read(fd, PROBE_IMU_ADDR,
   791	                                   PROBE_IMU_FIFO_DATA_OUT_L,
   792	                                   word, sizeof(word));
   793	              if (ret != 0)
   794	                {
   795	                  i2c_errors++;
   796	                  expected_valid = false;
   797	                  break;
   798	                }
   799	
   800	              fifo_words_read++;
   801	              raw = (int16_t)((uint16_t)word[0] |
   802	                              ((uint16_t)word[1] << 8));
   803	              if (!pattern_aligned)
   804	                {
   805	                  if (pattern_word != 0)
   806	                    {
   807	                      unexpected_frames++;
   808	                    }
   809	                  else
   810	                    {
   811	                      pattern_aligned = true;
   812	                      discard_remaining = PROBE_IMU_FIFO_PATTERN_WORDS;
   813	                    }
   814	                }
   815	
   816	              if (pattern_aligned && discard_remaining > 0)
   817	                {
   818	                  discard_remaining--;
   819	                  startup_discarded_words++;
   820	                }
   821	              else if (pattern_aligned)
   822	                {
   823	                  if (pattern_word < 3)
   824	                    {
   825	                      gyro[pattern_word] = raw;
   826	                      gyro_axis_mask |= 1u << pattern_word;
   827	                      if (pattern_word == 2)
   828	                        {
   829	                          if (gyro_axis_mask == 0x07)
   830	                            {
   831	                              gyro_samples++;
   832	                              gyro_ready = true;
   833	                            }
   834	                          else
   835	                            {
   836	                              unexpected_frames++;
   837	                              gyro_ready = false;
   838	                            }
   839	
   840	                          gyro_axis_mask = 0;
   841	                        }
   842	                    }
   843	                  else
   844	                    {
   845	                      accel[pattern_word - 3] = raw;
   846	                      accel_axis_mask |= 1u << (pattern_word - 3);
   847	                      if (pattern_word == 5)
   848	                        {
   849	                          if (accel_axis_mask == 0x07)
   850	                            {
   851	                              accel_samples++;
   852	                              if (gyro_ready)
   853	                                {
   854	                                  uint32_t complete_cycles_after =
   855	                                    words_to_read /
   856	                                    PROBE_IMU_FIFO_PATTERN_WORDS;
   857	
   858	                                  paired_samples++;
   859	                                  memset(&sample, 0, sizeof(sample));
   860	                                  sample.monotonic_us = drain_now_us -
   861	                                    (uint64_t)complete_cycles_after *
   862	                                    1000000ULL / PROBE_IMU_RAW_TARGET_HZ;
   863	                                  sample.sequence = imu_sequence++;
   864	                                  memcpy(sample.gyro, gyro,
   865	                                         sizeof(sample.gyro));
   866	                                  memcpy(sample.accel, accel,
   867	                                         sizeof(sample.accel));
   868	                                  sample.flags =
   869	                                    PROBE_IMU_SAMPLE_FLAG_ESTIMATED_TIME;
   870	                                  if (imu_gap_pending)
   871	                                    {
   872	                                      sample.flags |=
   873	                                        PROBE_IMU_SAMPLE_FLAG_GAP;
   874	                                    }
   875	
   876	                                  if (probe_game_submit_imu(&sample))
   877	                                    {
   878	                                      imu_gap_pending = false;
   879	                                    }
   880	                                  else
   881	                                    {
   882	                                      imu_gap_pending = true;
   883	                                    }
   884	                                }
   885	                              else
   886	                                {
   887	                                  unexpected_frames++;
   888	                                }
   889	                            }
   890	                          else
   891	                            {
   892	                              unexpected_frames++;
   893	                            }
   894	
   895	                          accel_axis_mask = 0;
   896	                          gyro_ready = false;
   897	                        }
   898	                    }
   899	                }
   900	
   901	              expected_pattern = (uint8_t)((pattern_word + 1) %
   902	                                             PROBE_IMU_FIFO_PATTERN_WORDS);
   903	              expected_valid = true;
   904	              pattern++;
   905	            }
   906	
   907	          if (ret != 0)
   908	            {
   909	              break;
   910	            }
   911	
   912	          /* Re-read status and continue draining until FIFO_EMPTY. */
   913	        }
   914	    }
   915	
   916	stop_irq:
   917	  if (irq_enabled)
   918	    {
   919	      cleanup_ret = board_imu_int1_disable();
   920	      if (cleanup_ret != 0 && restore_status == 0)
   921	        {
   922	          restore_status = cleanup_ret;
   923	        }
   924	      irq_enabled = false;
   925	    }
   926	
   927	  ret = probe_imu_read(fd, PROBE_IMU_ADDR, PROBE_IMU_FIFO_STATUS1,
   928	                       status, sizeof(status));
   929	  if (ret == 0)
   930	    {
   931	      end_depth_words = (uint16_t)status[0] |
   932	                        ((uint16_t)(status[1] & 0x07) << 8);
   933	    }
   934	  else
   935	    {
   936	      i2c_errors++;
   937	    }
   938	
   939	  if (fifo_started)
   940	    {
   941	      cleanup_ret = probe_imu_write_reg(fd, PROBE_IMU_ADDR,
   942	                                        PROBE_IMU_FIFO_CTRL5,
   943	                                        PROBE_IMU_FIFO_BYPASS);
   944	      if (cleanup_ret != 0 && restore_status == 0)
   945	        {
   946	          restore_status = cleanup_ret;
   947	        }
   948	    }
   949	
   950	restore:
   951	  /* Restore sensors, FIFO configuration/mode, pulse mode, then INT1. */
   952	
   953	  for (i = 7; i < 10; i++)
   954	    {
   955	      if (saved_valid[i])
   956	        {
   957	          cleanup_ret = probe_imu_write_reg(fd, PROBE_IMU_ADDR,
   958	                                            registers[i], saved[i]);
   959	          if (cleanup_ret != 0 && restore_status == 0)
   960	            {
   961	              restore_status = cleanup_ret;
   962	            }
   963	        }
   964	    }
   965	
   966	  for (i = 0; i < 5; i++)
   967	    {
   968	      if (saved_valid[i])
   969	        {
   970	          cleanup_ret = probe_imu_write_reg(fd, PROBE_IMU_ADDR,
   971	                                            registers[i], saved[i]);
   972	          if (cleanup_ret != 0 && restore_status == 0)
   973	            {
   974	              restore_status = cleanup_ret;
   975	            }
   976	        }
   977	    }
   978	
   979	  for (i = 5; i < 7; i++)
   980	    {
   981	      if (saved_valid[i])
   982	        {
   983	          cleanup_ret = probe_imu_write_reg(fd, PROBE_IMU_ADDR,
   984	                                            registers[i], saved[i]);
   985	          if (cleanup_ret != 0 && restore_status == 0)
   986	            {
   987	              restore_status = cleanup_ret;
   988	            }
   989	        }
   990	    }
   991	
   992	  if (semaphore_initialized)
   993	    {
   994	      sem_destroy(&g_imu_drdy_sem);
   995	    }
   996	
   997	  fifo_irq_count = __atomic_load_n(&g_imu_drdy_irq_count,
   998	                                    __ATOMIC_RELAXED);
   999	  end_us = start_us;
  1000	  if (start_us != 0 && clock_gettime(CLOCK_MONOTONIC, &now) == 0)
  1001	    {
  1002	      end_us = probe_timespec_us(&now);
  1003	    }
  1004	
  1005	  printf("openvela_ble_probe: IMU FIFO summary duration_ms=%llu"
  1006	         " elapsed_ms=%llu"
  1007	         " fifo_irq_count=%lu fifo_wake_count=%lu fifo_words_read=%lu"
  1008	         " gyro_samples=%lu accel_samples=%lu"
  1009	         " paired_six_axis_samples=%lu startup_discarded_words=%lu"
  1010	         " fifo_watermark_events=%lu fifo_overrun=%lu fifo_smart_full=%lu"
  1011	         " max_fifo_depth_words=%lu unpaired_or_unexpected_frames=%lu"
  1012	         " i2c_errors=%lu timeouts=%lu end_depth_words=%u\n",
  1013	         (unsigned long long)(start_us == 0 || end_us < start_us ? 0 :
