                  expected_valid = false;
                  break;
                }

              fifo_words_read++;
              raw = (int16_t)((uint16_t)word[0] |
                              ((uint16_t)word[1] << 8));
              if (!pattern_aligned)
                {
                  if (pattern_word != 0)
                    {
                      unexpected_frames++;
                    }
                  else
