 198	  uint32_t head = __atomic_load_n(&g_imu_head, __ATOMIC_RELAXED);
 199	  uint32_t tail = __atomic_load_n(&g_imu_tail, __ATOMIC_ACQUIRE);
 200	
 201	  if (!__atomic_load_n(&g_started, __ATOMIC_ACQUIRE))
 202	    {
 203	      return false;
 204	    }
 205	
 206	  if (head - tail >= PROBE_IMU_RING_DEPTH)
 207	    {
 208	      __atomic_fetch_add(&g_imu_ring_full, 1, __ATOMIC_RELAXED);
 209	      return false;
 210	    }
 211	
 212	  memcpy(&g_imu_ring[head % PROBE_IMU_RING_DEPTH], sample, sizeof(*sample));
 213	  __atomic_store_n(&g_imu_head, head + 1, __ATOMIC_RELEASE);
 214	  if ((sample->flags & PROBE_IMU_SAMPLE_FLAG_GAP) != 0)
 215	    {
 216	      __atomic_fetch_add(&g_imu_gap_samples, 1, __ATOMIC_RELAXED);
 217	    }
 218	
 219	  sem_post(&g_game_sem);
 220	  return true;
 221	}
