   360	static int i2c_normal_ops(struct sifli_i2c_master_s *bf0_i2c, struct i2c_msg_s * msg)
   361	{
   362	    int ret;
   363	
   364	    if (msg->flags & I2C_M_READ)
   365	    {
   366	        if (bf0_i2c->i2c_dma_flag)
   367	        {
   368	            HAL_DMA_Init(&bf0_i2c->dma.dma_rx);
   369	            ret = HAL_I2C_Master_Receive_DMA(&bf0_i2c->handle, msg->addr, msg->buffer, msg->length);
   370	        }
   371	        else
   372	#ifdef CONFIG_I2C_POLLED
   373	            ret = HAL_I2C_Master_Receive(&bf0_i2c->handle, msg->addr, msg->buffer, msg->length, MSEC2TICK(I2C_XFER_TIMEOUT));
   374	#else
   375	            ret = HAL_I2C_Master_Receive_IT(&bf0_i2c->handle, msg->addr, msg->buffer, msg->length);
   376	#endif
   377	    }
   378	    else
   379	    {
   380	        if (bf0_i2c->i2c_dma_flag)
   381	        {
   382	            HAL_DMA_Init(&bf0_i2c->dma.dma_tx);
   383	            ret = HAL_I2C_Master_Transmit_DMA(&bf0_i2c->handle, msg->addr, msg->buffer, msg->length);
   384	        }
   385	        else
   386	#ifdef CONFIG_I2C_POLLED
   387	            ret = HAL_I2C_Master_Transmit(&bf0_i2c->handle, msg->addr, msg->buffer, msg->length, MSEC2TICK(I2C_XFER_TIMEOUT));
   388	#else
   389	            ret = HAL_I2C_Master_Transmit_IT(&bf0_i2c->handle, msg->addr, msg->buffer, msg->length);
   390	#endif
   391	    }
   392	
   393	    return ret;
   394	}
