   322	static int sifli_i2c_configure(struct sifli_i2c_master_s *bf0_i2c, int addr, int freq, int addrmode)
   323	{
   324	    int ret=OK;
   325	
   326	    i2cinfo("i2c_bus_configure start");
   327	    DEBUGASSERT(bf0_i2c != NULL);
   328	
   329	    //if (bf0_i2c->frequency==addr)
   330	        //return ret;
   331	
   332	    if (addrmode & I2C_M_TEN)
   333	    {
   334	        bf0_i2c->handle.Init.AddressingMode = I2C_ADDRESSINGMODE_10BIT;
   335	        bf0_i2c->handle.Init.OwnAddress1 = (addr & 0x7fff);
   336	    }
   337	    else
   338	    {
   339	        bf0_i2c->handle.Init.AddressingMode = I2C_ADDRESSINGMODE_7BIT;
   340	        bf0_i2c->handle.Init.OwnAddress1 = (addr & 0x7fff) << 1;
   341	    }
   342	
   343	    bf0_i2c->handle.Init.ClockSpeed = freq;
   344	    bf0_i2c->handle.Init.GeneralCallMode = I2C_GENERALCALL_DISABLE;
   345	    bf0_i2c->handle.core = bf0_i2c->bf0_i2c_cfg->core;
   346	    bf0_i2c->handle.Mode = HAL_I2C_MODE_MASTER;
   347	
   348	    ret = HAL_I2C_Init(&(bf0_i2c->handle));
   349	    i2cinfo("i2c_bus_configure end");
   350	
   351	    return ret;
   352	}
