   240	static int i2cdrvr_ioctl(FAR struct file *filep, int cmd, unsigned long arg)
   241	{
   242	  FAR struct i2c_driver_s *priv;
   243	  FAR struct i2c_transfer_s *transfer;
   244	  int ret;
   245	
   246	  /* Sanity check */
   247	
   248	  DEBUGASSERT(filep->f_inode->i_private != NULL);
   249	  i2cinfo("cmd=%x arg=%08lx\n", cmd, arg);
   250	
   251	  /* Get our private data structure */
   252	
   253	  priv = filep->f_inode->i_private;
   254	
   255	#ifndef CONFIG_DISABLE_PSEUDOFS_OPERATIONS
   256	  /* Get exclusive access to the I2C driver state structure */
   257	
   258	  nxmutex_lock(&priv->lock);
   259	#endif
   260	
   261	  /* Process the IOCTL command */
   262	
   263	  switch (cmd)
   264	    {
   265	      /* Command:      I2CIOC_TRANSFER
   266	       * Description:  Perform an I2C transfer
   267	       * Argument:     A reference to an instance of struct i2c_transfer_s.
   268	       * Dependencies: CONFIG_I2C_DRIVER
   269	       */
   270	
   271	      case I2CIOC_TRANSFER:
   272	        {
   273	          /* Get the reference to the i2c_transfer_s structure */
   274	
   275	          transfer = (FAR struct i2c_transfer_s *)((uintptr_t)arg);
   276	          DEBUGASSERT(transfer != NULL);
   277	
   278	          /* Perform the transfer */
   279	
   280	          ret = I2C_TRANSFER(priv->i2c, transfer->msgv, transfer->msgc);
   281	        }
   282	        break;
   283	
   284	#ifdef CONFIG_I2C_RESET
   285	      /* Command:      I2CIOC_RESET
   286	       * Description:  Perform an I2C bus reset in an attempt to break loose
   287	       *               stuck I2C devices.
   288	       * Argument:     None
   289	       * Dependencies: CONFIG_I2C_DRIVER && CONFIG_I2C_RESET
   290	       */
   291	
   292	      case I2CIOC_RESET:
   293	        {
   294	          ret = I2C_RESET(priv->i2c);
   295	        }
   296	        break;
   297	#endif
   298	
   299	      default:
   300	        ret = -ENOTTY;
   320	}
