   576	 * Name: sifli_i2c_reset
   577	 *
   578	 * Description:
   579	 *   Reset an I2C bus
   580	 *
   581	 ****************************************************************************/
   582	
   583	#ifdef CONFIG_I2C_RESET
   584	static int sifli_i2c_reset(struct i2c_master_s *dev)
   585	{
   586	    struct sifli_i2c_master_s *bf0_i2c=(struct sifli_i2c_master_s *)dev;
   587	
   588	    nxmutex_lock(&bf0_i2c->lock);
   589	    HAL_I2C_Reset(&bf0_i2c->handle);
   590	    nxmutex_unlock(&bf0_i2c->lock);
   591	    return OK;
