   595	/****************************************************************************
   596	 * Name: sifli_i2c_pm_prepare
   597	 *
   598	 * Description:
   599	 *   Request the driver to prepare for a new power state. This is a
   600	 *   warning that the system is about to enter into a new power state.  The
   601	 *   driver should begin whatever operations that may be required to enter
   602	 *   power state.  The driver may abort the state change mode by returning
   603	 *   a non-zero value from the callback function.
   604	 *
   605	 * Input Parameters:
   606	 *   cb      - Returned to the driver.  The driver version of the callback
   607	 *             structure may include additional, driver-specific state
   608	 *             data at the end of the structure.
   609	 *   domain  - Identifies the activity domain of the state change
   610	 *   pmstate - Identifies the new PM state
   611	 *
   612	 * Returned Value:
   613	 *   0 (OK) means the event was successfully processed and that the driver
   614	 *   is prepared for the PM state change.  Non-zero means that the driver
   615	 *   is not prepared to perform the tasks needed achieve this power setting
   616	 *   and will cause the state change to be aborted.  NOTE:  The prepare
   617	 *   method will also be recalled when reverting from lower back to higher
   618	 *   power consumption modes (say because another driver refused a lower
   619	 *   power state change).  Drivers are not permitted to return non-zero
   620	 *   values when reverting back to higher power consumption modes!
   621	 *
   622	 ****************************************************************************/
   623	
   624	#ifdef CONFIG_PM
   625	static int sifli_i2c_pm_prepare(struct pm_callback_s *cb, int domain,
   626	                                  enum pm_state_e pmstate)
   627	{
   628	    struct sifli_i2c_master_s *priv =
   629	                           (struct sifli_i2c_master_s *)((char *)cb -
   630	                            offsetof(struct sifli_i2c_master_s, pm_cb));
   631	
   632	    /* Logic to prepare for a reduced power state goes here. */
   633	    switch (pmstate)
   634	    {
   635	        case PM_NORMAL:
   636	        case PM_IDLE:
   637	            break;
   638	        case PM_STANDBY:
   639	        case PM_SLEEP:
   640	            /* Check if exclusive lock for I2C bus is held. */
   641	            if (nxmutex_is_locked(&priv->lock))
   642	            {
   643	                /* Exclusive lock is held, do not allow entry to deeper PM states.*/
   644	                return -EBUSY;
   645	            }
   646	          break;
   647	        default:
   648	          /* Should not get here */
   649	          break;
   650	    }
