1716	  uint32_t generation;
1717	  uint32_t used;
1718	  bool synced;
1719	
1720	  if (probe_monotonic_ms(&monotonic_ms) < 0)
1721	    {
1722	      return -1;
1723	    }
1724	
1725	  pthread_mutex_lock(&g_state_lock);
1726	  generation = __atomic_load_n(&g_connection_generation, __ATOMIC_ACQUIRE);
1727	  if (!g_peer_connected)
1728	    {
1729	      pthread_mutex_unlock(&g_state_lock);
1730	      return -1;
1731	    }
1732	
1733	  used = g_gesture_rx_head - g_gesture_rx_tail;
1734	  if (used >= PROBE_GESTURE_QUEUE_DEPTH)
1735	    {
1736	      g_gesture_queue_full++;
1737	      pthread_mutex_unlock(&g_state_lock);
1738	      return -1;
1739	    }
1740	
1741	  synced = g_gesture_time_synced;
1742	  timestamp_ms = synced ?
1743	    g_gesture_sync_unix_ms +
1744	      (monotonic_ms - g_gesture_sync_monotonic_ms) : monotonic_ms;
1745	  if (synced)
1746	    {
1747	      flags |= 0x01;
1748	    }
1749	  else
1750	    {
1751	      flags &= (uint8_t)~0x01;
1752	    }
