1758	  record->packet_id = g_gesture_next_packet_id++;
1759	  record->event[0] = 1;
1760	  record->event[1] = 0x01;
1761	  probe_put_le16(&record->event[2], record->packet_id);
1762	  probe_put_le64(&record->event[4], timestamp_ms);
1763	  record->event[12] = gesture;
1764	  record->event[13] = confidence;
1765	  record->event[14] = flags;
1766	  record->event[15] = battery;
1767	  g_gesture_rx_head++;
1768	  g_gesture_enqueued++;
