    61	
    62	int clock_systime_timespec(FAR struct timespec *ts)
    63	{
    64	#ifdef CONFIG_RTC_HIRES
    65	  if (g_rtc_enabled)
    66	    {
    67	      irqstate_t flags;
    68	
    69	      up_rtc_gettime(ts);
    70	
    71	      flags = spin_lock_irqsave(&g_basetime_lock);
    72	      clock_timespec_subtract(ts, &g_basetime, ts);
    73	      spin_unlock_irqrestore(&g_basetime_lock, flags);
    74	    }
    75	  else
    76	    {
    77	      ts->tv_sec = 0;
    78	      ts->tv_nsec = 0;
    79	    }
    80	#elif defined(CONFIG_ALARM_ARCH) || \
    81	      defined(CONFIG_TIMER_ARCH) || \
    82	      defined(CONFIG_SCHED_TICKLESS)
    83	  up_timer_gettime(ts);
    84	#else
    85	  clock_ticks2time(ts, clock_systime_ticks());
    86	#endif
    87	  return 0;
    88	}
