257	/****************************************************************************
258	 * Name: up_timer_gettime
259	 *
260	 * Description:
261	 *   Return the elapsed time since power-up (or, more correctly, since
262	 *   up_timer_initialize() was called).  This function is functionally
263	 *   equivalent to:
264	 *
265	 *      int clock_gettime(clockid_t clockid, struct timespec *ts);
266	 *
267	 *   when clockid is CLOCK_MONOTONIC.
268	 *
269	 *   This function provides the basis for reporting the current time and
270	 *   also is used to eliminate error build-up from small errors in interval
271	 *   time calculations.
272	 *
273	 *   Provided by platform-specific code and called from the RTOS base code.
274	 *
275	 * Input Parameters:
276	 *   ts - Provides the location in which to return the up-time.
277	 *
278	 * Returned Value:
279	 *   Zero (OK) is returned on success; a negated errno value is returned on
280	 *   any failure.
281	 *
282	 * Assumptions:
283	 *   Called from the normal tasking context.  The implementation must
284	 *   provide whatever mutual exclusion is necessary for correct operation.
285	 *   This can include disabling interrupts in order to assure atomic register
286	 *   operations.
287	 *
288	 ****************************************************************************/
289	
290	int up_timer_gettime(struct timespec *ts)
291	{
292	  irqstate_t flags;
293	
294	  DEBUGASSERT(ts);
295	
296	  /* Temporarily disable the overflow counter.  NOTE that we have to be
297	   * careful here because  stm32_tc_getpending() will reset the pending
298	   * interrupt status.  If we do not handle the overflow here then, it will
299	   * be lost.
300	   */
301	
302	  flags    = enter_critical_section();
303	  sf32_get_ts(ts);
304	  leave_critical_section(flags);
305	
306	  return OK;
307	}
308	
