310	 * Name: up_timer_cancel
311	 *
312	 * Description:
313	 *   Cancel the interval timer and return the time remaining on the timer.
314	 *   These two steps need to be as nearly atomic as possible.
315	 *   nxsched_timer_expiration() will not be called unless the timer is
316	 *   restarted with up_timer_start().
317	 *
318	 *   If, as a race condition, the timer has already expired when this
319	 *   function is called, then that pending interrupt must be cleared so
320	 *   that up_timer_start() and the remaining time of zero should be
321	 *   returned.
322	 *
323	 *   NOTE: This function may execute at a high rate with no timer running (as
324	 *   when pre-emption is enabled and disabled).
325	 *
585	        up_timer_cancel(NULL);
586	    return OK;
587	}
