   136	    sec         = (uint32_t)(usec / USEC_PER_SEC);
   137	    ts->tv_sec  = sec;
   138	    ts->tv_nsec = (usec - (sec * USEC_PER_SEC)) * NSEC_PER_USEC;
   139	    
   140	    tmrinfo("usec=%llu ts=(%lu, %lu)\n",
   141	            usec, (unsigned long)ts->tv_sec, (unsigned long)ts->tv_nsec);
   142	}
   143	
   144	static void sf32_interval_handler(void)
   145	{
   146	  tmrinfo("Expired...\n");
   147	
   148	  /* Disable the compare interrupt now. */
   149	#ifdef CONFIG_SCHED_TICKLESS_ALARM
   150	  FAR struct timespec ts;
   151	
   152	  sf32_get_ts(&ts);
   153	  nxsched_alarm_expiration(&ts);
   154	#else
   155	  nxsched_timer_expiration();
   156	#endif
   157	}
   158	static void sf32_timing_handler(void)
   159	{
   160	  g_tickless.overflow++;
   161	}
   162	
   163	static int sf32_tickless_handler(int irq, void *context, void *arg)
   164	{
   165	  tmrinfo("tim_isr:%p\n", (void *)g_tickless.tim_handle.Instance->ISR);
   166	  if (__HAL_LPTIM_GET_FLAG(&g_tickless.tim_handle, LPTIM_FLAG_OF) != RESET)
   167	  {
   168	    sf32_timing_handler();
   169	  }
   170	
   171	  /* Output compare interrupt */
   172	  if (__HAL_LPTIM_GET_FLAG(&g_tickless.tim_handle, LPTIM_FLAG_OC) != RESET)
   173	  {
   174	    g_tickless.pending = false;
   175	    sf32_interval_handler();    
   176	  }
   177	  HAL_LPTIM_IRQHandler(&g_tickless.tim_handle);
   178	
   179	  return OK;
   180	}

