  pthread_mutex_lock(&g_state_lock);
  ready = g_peer_connected && g_notify_enabled;
  memcpy(&peer_addr, &g_peer_addr, sizeof(peer_addr));
  pthread_mutex_unlock(&g_state_lock);

  if (!ready)
    {
      printf("openvela_ble_probe: TX notification not subscribed\n");
      return BT_STATUS_NOT_READY;
    }

  return bt_gatts_notify(srv_handle, &peer_addr, PROBE_TX_HANDLE,
                         value, length);
}

static uint32_t probe_elapsed_ms(const struct timespec *started_at)
{
  struct timespec ended_at;
  int64_t seconds;
  int64_t nanoseconds;
  uint64_t milliseconds;

  if (clock_gettime(CLOCK_MONOTONIC, &ended_at) < 0)
    {
      return 0;
    }

  seconds = ended_at.tv_sec - started_at->tv_sec;
  nanoseconds = ended_at.tv_nsec - started_at->tv_nsec;
  if (nanoseconds < 0)
    {
      seconds--;
      nanoseconds += 1000000000;
    }

  if (seconds < 0)
    {
      return 0;
    }

  milliseconds = (uint64_t)seconds * 1000 +
                 (uint64_t)nanoseconds / 1000000;
  return milliseconds > UINT32_MAX ? UINT32_MAX : (uint32_t)milliseconds;
}

