 447	static uint64_t probe_timespec_us(const struct timespec *time)
 448	{
 449	  uint64_t raw_us = (uint64_t)time->tv_sec * 1000000ULL +
 450	                    (uint64_t)time->tv_nsec / 1000ULL;
 451	  uint32_t low_us = (uint32_t)raw_us;
 452	  uint64_t extended_us;
 453	
 454	  /* The SF32LB52 monotonic source can expose a 32-bit microsecond rollover.
 455	   * Extend that counter under a short lock so all Probe threads share one
 456	   * 64-bit epoch.  Callers still transfer timestamps through their existing
 457	   * release/acquire SPSC slots rather than sharing mutable 64-bit fields.
 458	   */
 459	
 460	  pthread_mutex_lock(&g_monotonic_lock);
 461	  if (!g_monotonic_extended_valid)
 462	    {
 463	      g_monotonic_epoch_us = raw_us & ~UINT64_C(0xffffffff);
 464	      g_monotonic_extended_valid = true;
 465	    }
 466	  else if (low_us < g_monotonic_last_low_us &&
 467	           g_monotonic_last_low_us - low_us > UINT32_C(0x80000000))
 468	    {
 469	      g_monotonic_epoch_us += UINT64_C(0x100000000);
 470	    }
 471	
 472	  extended_us = g_monotonic_epoch_us + low_us;
 473	  if (extended_us < g_monotonic_last_us)
 474	    {
 475	      extended_us = g_monotonic_last_us;
 476	    }
 477	
 478	  g_monotonic_last_low_us = low_us;
 479	  g_monotonic_last_us = extended_us;
 480	  pthread_mutex_unlock(&g_monotonic_lock);
 481	  return extended_us;
 482	}
 483	
 484	static void probe_timespec_add_ms(struct timespec *time, uint32_t ms)
 485	{
 486	  uint64_t nsec = (uint64_t)time->tv_nsec +
 487	                  (uint64_t)ms * 1000000ULL;
 488	
 489	  time->tv_sec += (time_t)(nsec / 1000000000ULL);
 490	  time->tv_nsec = (long)(nsec % 1000000000ULL);
 491	}
