1755	/* Future gesture producers must use this bounded publisher rather than
1756	 * calling a GATT API.  It is task-context only, never ISR-context.
1757	 */
1758	
1759	static int probe_publish_gesture(uint8_t gesture, uint8_t confidence,
1760	                                 uint8_t flags, uint8_t battery,
1761	                                 uint64_t event_monotonic_us)
1762	{
1763	  struct probe_gesture_record_s *record;
1764	  uint64_t now_monotonic_us;
1765	  uint64_t timestamp_ms;
1766	  uint32_t generation;
1767	  uint32_t used;
1768	  bool synced;
1769	
1770	  if (probe_monotonic_us(&now_monotonic_us) < 0)
1771	    {
1772	      return -1;
1773	    }
1774	
1775	  if (event_monotonic_us == 0)
1776	    {
1777	      event_monotonic_us = now_monotonic_us;
1778	    }
1779	
1780	  pthread_mutex_lock(&g_state_lock);
1781	  generation = __atomic_load_n(&g_connection_generation, __ATOMIC_ACQUIRE);
1782	  if (!g_peer_connected)
1783	    {
1784	      pthread_mutex_unlock(&g_state_lock);
1785	      return -1;
1786	    }
1787	
1788	  used = g_gesture_rx_head - g_gesture_rx_tail;
1789	  if (used >= PROBE_GESTURE_QUEUE_DEPTH)
1790	    {
1791	      g_gesture_queue_full++;
1792	      pthread_mutex_unlock(&g_state_lock);
1793	      return -1;
1794	    }
1795	
1796	  synced = g_gesture_time_synced;
1797	  if (synced && event_monotonic_us < g_gesture_sync_monotonic_us)
1798	    {
1799	      event_monotonic_us = now_monotonic_us;
1800	    }
1801	
1802	  timestamp_ms = synced ?
1803	    g_gesture_sync_unix_ms +
1804	      (event_monotonic_us - g_gesture_sync_monotonic_us) / 1000ULL :
1805	    event_monotonic_us / 1000ULL;
1806	  if (synced)
1807	    {
1808	      flags |= 0x01;
1809	    }
1810	  else
1811	    {
1812	      flags &= (uint8_t)~0x01;
1813	    }
1814	
1815	  record = &g_gesture_queue[g_gesture_rx_head %
1816	                            PROBE_GESTURE_QUEUE_DEPTH];
1817	  memset(record, 0, sizeof(*record));
1818	  record->connection_generation = generation;
1819	  record->packet_id = g_gesture_next_packet_id++;
1820	  record->event[0] = 1;
1821	  record->event[1] = 0x01;
1822	  probe_put_le16(&record->event[2], record->packet_id);
1823	  probe_put_le64(&record->event[4], timestamp_ms);
1824	  record->event[12] = gesture;
1825	  record->event[13] = confidence;
1826	  record->event[14] = flags;
1827	  record->event[15] = battery;
1828	  g_gesture_rx_head++;
1829	  g_gesture_enqueued++;
1830	  pthread_mutex_unlock(&g_state_lock);
1831	
1832	  sem_post(&g_rx_sem);
1833	  return 0;
1834	}
1835	
1836	static void probe_gesture_time_sync(const uint8_t *value)
1837	{
1838	  uint64_t monotonic_us;
1839	  uint64_t unix_ms;
1840	
1841	  if (probe_monotonic_us(&monotonic_us) < 0)
1842	    {
1843	      printf("openvela_ble_probe: gesture time sync clock failed\n");
1844	      return;
1845	    }
1846	
1847	  pthread_mutex_lock(&g_state_lock);
1848	  unix_ms = probe_get_le64(value);
1849	  g_gesture_sync_unix_ms = unix_ms;
1850	  g_gesture_sync_monotonic_us = monotonic_us;
1851	  g_gesture_time_synced = true;
1852	  pthread_mutex_unlock(&g_state_lock);
1853	  printf("openvela_ble_probe: gesture time synchronized unix_ms=%" PRIu64
1854	         " monotonic_us=%" PRIu64 "\n", unix_ms, monotonic_us);
1855	}
