 484	static void probe_timespec_add_ms(struct timespec *time, uint32_t ms)
 485	{
 486	  uint64_t nsec = (uint64_t)time->tv_nsec +
 487	                  (uint64_t)ms * 1000000ULL;
 488	
 489	  time->tv_sec += (time_t)(nsec / 1000000000ULL);
 490	  time->tv_nsec = (long)(nsec % 1000000000ULL);
 491	}
