    96	static void sf32_get_ts(FAR struct timespec * ts)
    97	{
    98	    uint64_t usec;
    99	    uint32_t counter;
   100	    uint32_t overflow;
   101	    uint32_t sec;
   102	    int pending;
   103	
   104	    overflow = g_tickless.overflow;
   105	    pending  = __HAL_LPTIM_GET_FLAG(&g_tickless.tim_handle, LPTIM_FLAG_OF);
   106	    counter  = lp_timer_counter_get(&g_tickless);
   107	    
   108	    /* If an interrupt was pending before we re-enabled interrupts,
   109	     * then the overflow needs to be incremented.
   110	     */
   111	    
   112	    if (pending)
   113	      {
   114	        __HAL_LPTIM_CLEAR_FLAG(&g_tickless.tim_handle, LPTIM_ICR_OFCLR);
   115	    
   116	        /* Increment the overflow count and use the value of the
   117	         * guaranteed to be AFTER the overflow occurred.
   118	         */    
   119	        overflow++;    
   120	        g_tickless.overflow = overflow;
   121	      }
   122	        
   123	    tmrinfo("counter=%lu, overflow=%lu, pending=%i\n",
   124	           (unsigned long)counter, (unsigned long)overflow, pending);
   125	    
   126	    /* Convert the whole thing to units of microseconds.
   127	     *
   128	     *   frequency = ticks / second
   129	     *   seconds   = ticks * frequency
   130	     *   usecs     = (ticks * USEC_PER_SEC) / frequency;
   131	     */
   132	    usec = ((((uint64_t)overflow << 24) + (uint64_t)counter) * USEC_PER_SEC) /
   133	           g_tickless.frequency;
   134	    
   135	    /* And return the value of the timer */    
   136	    sec         = (uint32_t)(usec / USEC_PER_SEC);
   137	    ts->tv_sec  = sec;
   138	    ts->tv_nsec = (usec - (sec * USEC_PER_SEC)) * NSEC_PER_USEC;
   139	    
   140	    tmrinfo("usec=%llu ts=(%lu, %lu)\n",
   141	            usec, (unsigned long)ts->tv_sec, (unsigned long)ts->tv_nsec);
   142	}
