   124	           (unsigned long)counter, (unsigned long)overflow, pending);
   125	    
   126	    /* Convert the whole thing to units of microseconds.
   127	     *
   128	     *   frequency = ticks / second
   129	     *   seconds   = ticks * frequency
   130	     *   usecs     = (ticks * USEC_PER_SEC) / frequency;
   131	     */
   132	    usec = ((((uint64_t)overflow << 24) + (uint64_t)counter) * USEC_PER_SEC) /
   133	           g_tickless.frequency;
   134	    
   135	    /* And return the value of the timer */    
   136	    sec         = (uint32_t)(usec / USEC_PER_SEC);
   137	    ts->tv_sec  = sec;
   138	    ts->tv_nsec = (usec - (sec * USEC_PER_SEC)) * NSEC_PER_USEC;
   139	    
   140	    tmrinfo("usec=%llu ts=(%lu, %lu)\n",
   141	            usec, (unsigned long)ts->tv_sec, (unsigned long)ts->tv_nsec);
   142	}
