  1659	static uint32_t probe_elapsed_ms(const struct timespec *started_at)
  1660	{
  1661	  struct timespec ended_at;
  1662	  int64_t seconds;
  1663	  int64_t nanoseconds;
  1664	  uint64_t milliseconds;
  1665	
  1666	  if (clock_gettime(CLOCK_MONOTONIC, &ended_at) < 0)
  1667	    {
  1668	      return 0;
  1669	    }
  1670	
  1671	  seconds = ended_at.tv_sec - started_at->tv_sec;
  1672	  nanoseconds = ended_at.tv_nsec - started_at->tv_nsec;
  1673	  if (nanoseconds < 0)
  1674	    {
  1675	      seconds--;
  1676	      nanoseconds += 1000000000;
  1677	    }
  1678	
  1679	  if (seconds < 0)
  1680	    {
  1681	      return 0;
  1682	    }
  1683	
  1684	  milliseconds = (uint64_t)seconds * 1000 +
  1685	                 (uint64_t)nanoseconds / 1000000;
  1686	  return milliseconds > UINT32_MAX ? UINT32_MAX : (uint32_t)milliseconds;
  1687	}
